 28	/**
 29	 * PreParser state for checking delimiter matching.  Note that
 30	 * this class supports only a single state-modifying transaction.
 31	 * In other words, calls to {@link #start()}, {@link #commit()},
 32	 * and {@link #abort()} cannot be nested within each other.
 33	 */
 34	public class PreParserState implements State {
 35	
 36	    /** The list of left delimiters. */
 37	    private List<IdOrOp> lefts;
 38	
 39	    /** The beginning keywords matching with "end". */
 40	    private List<String> keywords;
 41	
 42	    /** The file to report mismatched delimiters. */
 43	    private BufferedWriter writer;
 44	
 45	    /** Nested component/API definitions are not allowed. */
 46	    private boolean sawCompilation = false;
 47	
 48	    /** Operator declarations are not allowed in block expressions. */
 49	    private boolean inBlock = false;
 50	    private boolean sawFn = false;
 51	
 52	    /** Region annotation by "at" should be followed by "do". */
 53	    private Option<Span> sawAt = Option.<Span>none();
 54	
 55	    /** Create a new preparser state object. */
 56	    public PreParserState() {
 57	        reset("No file yet!");
 58	    }
 59	
 60	    /** Initialize the map of matching keywords. */
 61	    public void init(BufferedWriter wr) {
 62	        writer = wr;
 63	        String[] ends = new String[]{"api", "component", "trait", "object", "grammar",
 64	                                     "do", "case", "if", "try", "typecase"};
 65	        keywords = new ArrayList<String>(java.util.Arrays.asList(ends));
 66	    }
 67	
 68	    public void reset(String file) {
 69	        lefts = new ArrayList<IdOrOp>();
 70	    }
 71	
 72	    public void start() { }
 73	    public void commit() { }
 74	    public void abort() { }
 75	
 76	    /** Record a left delimiter. */
 77	    public void left(IdOrOp open) {
 78	        Debug.debug( Debug.Type.PARSER, 1, "Left delimiter ", open );
 79	        String token = open.getText();
 80	        if ( token.equals("component") || token.equals("api") ) {
 81	            if ( sawCompilation )
 82	                log(NodeUtil.getSpan(open),
 83	                    "Nested " + token + " definitions are not allowed.");
 84	            sawCompilation = true;
 85	        }
 86	        if ( lefts.isEmpty() || !isQuote(lefts.get(0).getText()) )
 87	            lefts.add(0, open);
 88	    }
 89	
 90	    public void left(Span span, String open) {
 91	        left( NodeFactory.makeId(span, open) );
 92	    }
 93	
 94	    private void emptyLefts(IdOrOp close) {
 95	        Debug.debug( Debug.Type.PARSER, 1,
 96	                     "right: Unmatched delimiter \"" + close + "\"." );
 97	        log(NodeUtil.getSpan(close),
 98	            "Unmatched delimiter \"" + close + "\".");
 99	    }
100	
101	    /** Check a right delimiter. */
102	    public void right(IdOrOp close) {
103	        Debug.debug( Debug.Type.PARSER, 1, "Right delimiter ", close );
104	        if ( lefts.isEmpty() ) emptyLefts(close);
105	        else {
106	            IdOrOp open = lefts.remove(0);
107	            /* label Id /end Id -- covered by handleEnd
108	             * (if ... )        -- covered by matches
109	             * (if ... end)     -- covered by matches
110	             * (if ... end ...) -- here
111	             */
112	            if ( open.getText().equals("(if") && close.getText().equals("end") ) {
113	                lefts.add(0, NodeFactory.makeId(NodeUtil.getSpan(open), "("));
114	            } else if ( open.getText().startsWith("label$") ) {
115	                log(NodeUtil.spanTwo(open, close),
116	                    "Missing label at the end of a label expression.");
117	            } else if ( ! matches(open, close) ) {
118	                Debug.debug( Debug.Type.PARSER, 1,
119	                             "right: Unmatched delimiter \"" + close + "\"." );
120	                log(NodeUtil.spanTwo(NodeUtil.getSpan(open),
121	                                     NodeUtil.getSpan(close)),
122	                    "Unmatched delimiters \"" + open + "\" and \"" + close + "\".");
123	            }
124	            if ( open.getText().equals("(if") && close.getText().equals(")") )
125	                inBlock = false;
126	        }
127	    }
128	
129	    public void right(Span span, String close) {
130	        right( NodeFactory.makeId(span, close) );
131	    }
132	
133	    public void handleLabelEnd(Span span, Id id) {
134	        Debug.debug( Debug.Type.PARSER, 1, "HandleLabelEnd");
135	        Id close = NodeFactory.makeId(span, "end");
136	        if ( lefts.isEmpty() ) emptyLefts(close);
137	        else {
138	            IdOrOp open = lefts.remove(0);
139	            String openText = open.getText();
140	            if ( openText.startsWith("label$") ) {
141	                String openLabel = openText.substring(6);
142	                String closeLabel = id.getText();
143	                if ( ! openLabel.equals(closeLabel) )
144	                    log(NodeUtil.spanTwo(NodeUtil.getSpan(open), span),
145	                        "Opening label must match closing label.");
146	            } else {
147	                lefts.add(0, open);
148	                handleEnd(span);
149	            }
150	        }
151	    }
152	
153	    public void handleDo(Span span) {
154	        Debug.debug( Debug.Type.PARSER, 1, "HandleDo");
155	        sawAt = Option.<Span>none();
156	        if ( ! lefts.isEmpty() && lefts.get(0).getText().equals("also") )
157	            right( span, "do" );
158	        else left( span, "do" );
159	    }
160	
161	    public void handleAt(Span span) {
162	        Debug.debug( Debug.Type.PARSER, 1, "HandleAt");
163	        sawAt = Option.<Span>some(span);
164	    }
165	
166	    public void handleOpr(Span span) {
167	        Debug.debug( Debug.Type.PARSER, 1, "HandleOpr");
168	        for ( IdOrOp left : lefts ) {
169	            if ( left.getText().equals("object") ) return;
170	            if ( left.getText().equals("do") ||
171	                 left.getText().startsWith("label$") ||
172	                 inBlock )
173	                log(span, "Operator declarations are not allowed in block expressions.");
174	        }
175	    }
176	
177	    public void beginBlock() {
178	        inBlock = true;
179	    }
180	
181	    public void handleFn() {
182	        sawFn = true;
183	    }
184	
185	    // "=>" does not introduce a block for import aliases and fn expressions.
186	    public void handleDoubleArrow() {
187	        if ( sawFn ) sawFn = false;
188	        else if ( ! lefts.isEmpty() && ! lefts.get(0).getText().equals("{") )
189	            inBlock = true;
190	    }
191	
192	    public void handleEnd(Span span) {
193	        if ( ! lefts.isEmpty() &&
194	             ! lefts.get(0).getText().equals("object") )
195	            inBlock = false;
196	        right(span, "end");
197	    }
198	
199	    public void quote(Span span, String token) {
200	        Debug.debug( Debug.Type.PARSER, 1, "Quote ", token);
201	        if ( lefts.isEmpty() )
202	            left( NodeFactory.makeId(span, token) );
203	        else {
204	            if ( matches(lefts.get(0).getText(), token) )
205	                lefts.remove(0);
206	            else
207	                left( NodeFactory.makeId(span, token) );
208	        }
209	    }
210	
211	    public void report() {
212	        if ( ! lefts.isEmpty() ) {
213	            for ( IdOrOp left : lefts ) {
214	                Debug.debug( Debug.Type.PARSER, 1,
215	                             "report: Unmatched delimiter \"" + left + "\"." );
216	                log(NodeUtil.getSpan(left),
217	                    "Unmatched delimiter \"" + left + "\".");
218	            }
219	        }
220	        if ( sawAt.isSome() )
221	            log(sawAt.unwrap(), "Unmatched delimiter \"at\".");
222	    }
223	
224	    private void log(Span span, String message) {
225	        NodeUtil.log(writer, span, message);
226	    }
227	
228	    private boolean isQuote(String token) {
229	        String[] all = new String[]{"\\\"", "\u201c"};
230	        List<String> quotes = new ArrayList<String>(java.util.Arrays.asList(all));
231	        return quotes.contains( token );
232	    }
233	
234	    /** Check whether the given delimiters are matching delimiters. */
235	    private boolean matches(IdOrOp open, IdOrOp close) {
236	        String left = open.getText();
237	        String right = close.getText();
238	        if ( open  instanceof Id && close instanceof Id )
239	            return matches(left, right);
240	        else if ( open  instanceof Op && close instanceof Op )
241	            return PrecedenceMap.ONLY.matchedBrackets(left, right);
242	        else return false;
243	    }
244	
245	    private boolean matches(String left, String right) {
246	        if ( keywords.contains(left) ) return right.equals("end");
247	        else if ( left.equals("also") ) return right.equals("do");
248	        else if ( left.equals("(if") ) return ( right.equals(")") || right.equals("end)") );
249	        else if ( left.equals("(") ) return right.equals(")");
250	        else if ( left.equals("[") ) return right.equals("]");
251	        else if ( left.equals("{") ) return right.equals("}");
252	        else if ( left.equals("[\\") || left.equals("\u27e6") )
253	            return ( right.equals("\\]") || right.equals("\u27e7") );
254	        else if ( left.equals("\\\"") || left.equals("\u201c") )
255	            return ( right.equals("\\\"") || right.equals("\u201d") );
256	        else if ( left.equals("`") || left.equals("'") || left.equals("\u2018") )
257	            return ( right.equals("'") || right.equals("\u2019") );
258	        else return false;
259	    }
260	}
